-- GENERATED by apps/xkcd/bundle.py from tools/gamekit/gamekit.lua, src/xk.lua and src/lock/lock.lua -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

local X = (function()
-- xkcd pieces that need no screen: the JSON interface's addresses, a comic from its JSON, a PNG's
-- size from its header, fitting, the public resizer's address for pictures too big for the reader,
-- the saved-comic lines (cache.txt, lock.txt) and Random.
--
-- xkcd.com/info.0.json is the latest comic, xkcd.com/<n>/info.0.json any other: num, title, alt (the
-- text under the joke), img (a PNG on imgs.xkcd.com), year, month, day. There is no comic 404.

local X = {}

X.SITE = 'https://xkcd.com/'
X.MAX_SIDE = 1024               -- ctx.image:decode refuses a picture larger than this either way

-- percent-encoding without %w (which follows the C locale and may take bytes of UTF-8 letters)
function X.enc(s)
  return (tostring(s):gsub('[^A-Za-z0-9%-%._~]', function(c) return string.format('%%%02X', c:byte()) end))
end

function X.json_url(n) return n and (X.SITE .. n .. '/info.0.json') or (X.SITE .. 'info.0.json') end
function X.page_url(n) return X.SITE .. n .. '/' end

-- every picture through images.weserv.nl (the resizer the rss-opds Worker uses; no account), at
-- exactly the size it is shown: inside bw x bh, at most twice its own size (sw x sh, when known),
-- greyscale at full contrast. xkcd's lines are thin and grey at their edges; the reader's dithering
-- turned them into dotted lines, while this keeps them whole (checked 2026-11-13). Its own resampling
-- is better than the reader's, which only scales down.
function X.weserv_url(img, bw, bh, sw, sh)
  local w, h = bw, bh
  if sw and sh and sw > 0 and sh > 0 then w, h = math.min(bw, 2 * sw), math.min(bh, 2 * sh) end
  return 'https://images.weserv.nl/?url=' .. X.enc(img) .. '&w=' .. math.floor(w) .. '&h=' .. math.floor(h)
    .. '&fit=inside&output=png&filt=greyscale&con=100'
end

-- the decoded JSON as a comic; nil without a number. Interactive (shown as title, alt and a QR
-- code): no PNG or JPEG picture, or extra parts (scripts, frames) the reader cannot run.
function X.comic(d)
  if type(d) ~= 'table' then return nil end
  local num = tonumber(d.num)
  if not num then return nil end
  local img = type(d.img) == 'string' and d.img or ''
  local low = img:lower()
  local pic = low:match('%.png$') or low:match('%.jpe?g$')
  local y, m, dd = tonumber(d.year), tonumber(d.month), tonumber(d.day)
  return { num = math.floor(num), title = tostring(d.safe_title or d.title or ''), alt = tostring(d.alt or ''), img = img,
           date = (y and m and dd) and string.format('%04d-%02d-%02d', y, m, dd) or '',
           interactive = (not pic) or d.extra_parts ~= nil }
end

-- a PNG's width and height from its IHDR chunk; nil when it is not a PNG
function X.png_size(b)
  if type(b) ~= 'string' or #b < 24 or b:sub(1, 8) ~= '\137PNG\r\n\26\n' or b:sub(13, 16) ~= 'IHDR' then return nil end
  local w, h = string.unpack('>I4I4', b, 17)
  return w, h
end
-- what the bytes are: 'png', 'jpg' or nil
function X.ext(b)
  if type(b) ~= 'string' then return nil end
  if b:sub(1, 4) == '\137PNG' then return 'png' end
  if b:sub(1, 3) == '\255\216\255' then return 'jpg' end
  return nil
end

-- w x h made to fit aw x ah, keeping its shape; never larger than it is
function X.fit(w, h, aw, ah)
  local s = math.min(1, aw / w, ah / h)
  return math.floor(w * s), math.floor(h * s)
end
function X.landscape(w, h) return w > h end

-- one comic as a line of text (cache.txt, lock.txt), and back
local function clean(s) return (tostring(s or ''):gsub('[\t\r\n]+', ' ')) end
function X.line(c)
  return table.concat({ c.num, clean(c.title), clean(c.alt), clean(c.img), clean(c.date), c.interactive and '1' or '0' }, '\t')
end
function X.parse_line(s)
  local num, title, alt, img, date, inter = tostring(s or ''):match('^(%d+)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([^\t]*)\t([01])$')
  if not num then return nil end
  return { num = tonumber(num), title = title, alt = alt, img = img, date = date, interactive = inter == '1' }
end

-- a comic number from r in [0, 1): 1..latest, never 404 (there is none)
function X.random(latest, r)
  local n = math.min(latest, math.floor(r * latest) + 1)
  if n == 404 then n = latest > 404 and 405 or 403 end
  return n
end

return X
end)()

-- xkcd's sleep screen (bundle.py puts tools/gamekit/gamekit.lua as `kit` and src/xk.lua as `X` in
-- front): the latest comic, kept in its own files (lock.txt: "<kind>\t<X.line>" and "at=<when
-- looked>"; lock.png, or lock.jpg when reduced), with the time it was looked for. When the interval
-- chosen in the app (settings.txt lockevery, hours) has passed, xkcd.com/info.0.json is asked again
-- while locked (API 2.26: ctx.net in a lock session whose manifest block has "net": true), and the
-- picture only when the number is new. Requests go out in on_load; a timer wake holds its frame
-- until the answers, the first session draws at once and again after them. ctx.lock:done() ends
-- the session once nothing is pending. Each session sets the next wake an hour away (the longest
-- the host allows; the reader aligns it to the hour).

local W, H = 480, 800
local MAX_WAKE_S = 3600         -- ctx.lock:set_interval takes 30-3600 s
local SLACK_S = 120             -- a wake may come early (seen: up to a minute)
local pending = false           -- requests out in this session
-- store: cut (the store's API gives a lock screen no network; tools/store_export.py drops this)
local asked = false
local holding = false           -- an early wake waiting for the aligned time it was woken for
-- store: end

local function read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
local function write(name, s) pcall(function() ctx.storage:write(name, s) end) end
local function clock()
  local ok, t = pcall(function() return ctx.clock:now() end)
  return (ok and type(t) == 'table') and t or {}
end
local function now_sec() return math.floor(tonumber(clock().epoch_sec) or 0) end
local function offset()
  local t = clock()
  if not tonumber(t.hour) then return 0 end
  local wall = t.hour * 3600 + (t.minute or 0) * 60 + (t.second or 0)
  local off = (wall - now_sec() % 86400) % 86400
  if off > 14 * 3600 then off = off - 86400 end
  return math.floor(off / 900 + 0.5) * 900
end
local function stamp(at)
  if not at then return nil end
  local off = offset()
  local days = (now_sec() + off) // 86400 - (at + off) // 86400
  local hm = string.format('%02d:%02d', (at + off) % 86400 // 3600, (at + off) % 3600 // 60)
  if days <= 0 then return 'updated ' .. hm end
  return days == 1 and ('updated yesterday ' .. hm) or ('updated ' .. days .. ' days ago')
end

-- lock.txt: the comic, its kind (png, jpg, rjpg reduced, none) and when it was looked for
local function saved()
  local s = read('lock.txt')
  if not s then return nil end
  local kind, rest = s:match('^(%a+)\t([^\n]*)')
  local c = rest and X.parse_line(rest)
  if not c then return nil end
  return { kind = kind, c = c, at = tonumber(s:match('\nat=(%d+)')) }
end
local function save(kind, c, at) write('lock.txt', kind .. '\t' .. X.line(c) .. '\nat=' .. at) end
local function pic(kind) return (kind == 'png') and 'lock.png' or 'lock.jpg' end

-- store: cut
local function wlog(s)
  pcall(function()
    local w = (now_sec() + offset()) % 86400
    local lines = {}
    for l in (read('wakes.txt') or ''):gmatch('[^\n]+') do lines[#lines + 1] = l end
    lines[#lines + 1] = string.format('%02d:%02d:%02d ', w // 3600, w % 3600 // 60, w % 60) .. s
    while #lines > 20 do table.remove(lines, 1) end
    ctx.storage:write('wakes.txt', table.concat(lines, '\n') .. '\n')
  end)
end

-- an early timer wake ending before the aligned time it was woken for gets a second wake at that
-- time: hold the session with ctx:after (it runs in a 2.26 lock session) until 2 s past it
local function hold_if_early()
  if not (ctx.lock and ctx.lock.reason == 'timer') then return end
  local iv = tonumber(ctx.lock.interval_sec) or MAX_WAKE_S
  local rem = (iv - (now_sec() + offset()) % iv) % iv
  if rem == 0 or rem > SLACK_S then return end
  local ok, tm = pcall(function()
    return ctx:after((rem + 2) * 1000, function()
      holding = false
      pcall(function() ctx:invalidate() end)
    end)
  end)
  holding = ok and tm ~= nil
end

local function finish(what)
  pending = false
  wlog(what)
  pcall(function() ctx:invalidate() end)              -- draw again; that draw ends the session
end
local function request(url, save_name, fn, range)
  local req = { url = url, method = 'GET', timeout_ms = 30000, headers = { ['User-Agent'] = 'XteinkLicoriceXKCD/1.0' } }
  if save_name then req.save = { to = 'storage', name = save_name } end
  if range then req.headers.Range = range end
  local ok, job = pcall(function()
    return ctx.net:request(req, function(c, res)
      local okc, e = pcall(fn, res)
      if not okc then finish('error: ' .. tostring(e)) end
    end)
  end)
  return ok and job ~= nil
end
local function bad(res)
  if type(res) ~= 'table' or res.ok == false then return 'no network' end
  local code = tonumber(res.status) or 0
  if code >= 400 then return 'HTTP ' .. code end
  return nil
end

-- the picture of a new comic, made for the sleep screen as the app's are: its size from its first
-- 64 bytes, then the resizer makes it for the box below the title (at most twice its size),
-- greyscale at full contrast (X.weserv_url)
local BOX_W, BOX_H = W - 16, H - 50 - 70
local function fetch_pic(c)
  local sent = request(c.img, nil, function(res)
    local b = bad(res)
    if b == 'no network' then finish('picture: ' .. b); return end
    local sw, sh
    if not b and type(res.body) == 'string' then sw, sh = X.png_size(res.body) end
    local sent2 = request(X.weserv_url(c.img, BOX_W, BOX_H, sw, sh), 'lock.png', function(r2)
      local b2 = bad(r2)
      if b2 then finish('picture: ' .. b2); return end
      if not r2.saved then finish('picture not saved: ' .. tostring(r2.err)); return end
      pcall(function() ctx.storage:remove('lock.jpg') end)
      save('png', c, now_sec())
      finish('new comic ' .. c.num)
    end)
    if not sent2 then finish('picture not sent') end
  end, 'bytes=0-63')
  if not sent then finish('picture not sent') end
end

-- -> what it did, for the log
local function try_refresh(s)
  if asked then return 'asking' end
  if not ctx.net then return 'no network on the lock screen' end
  asked = true
  pending = true
  local sent = request(X.json_url(nil), nil, function(res)
    local b = bad(res)
    if b then finish('latest: ' .. b); return end
    local okd, d = pcall(function() return ctx.json:decode(res.body) end)
    local c = okd and X.comic(d)
    if not c then finish('latest: not a comic'); return end
    if s and s.c.num >= c.num then
      save(s.kind, s.c, now_sec())
      finish('no new comic (' .. c.num .. ')')
    elseif c.interactive then
      save('none', c, now_sec())
      finish('new comic ' .. c.num .. ' (interactive)')
    else
      fetch_pic(c)
    end
  end)
  if not sent then pending = false; return 'not sent' end
  return 'asking'
end
-- store: end

function on_draw(c, gg)
  if not gg then return end
  local ok, err = pcall(function()
    gg:clear(0)
    local s = saved()
    if not s then
      local y = 300
      for _k, l in ipairs(kit.wrap('xkcd: open the app once (with Wi-Fi) to show the latest comic here.', 'medium', W - 48)) do
        gg:text(24, y, l, { font = kit.font('medium') }); y = y + 32
      end
      return
    end
    local title = 'xkcd ' .. s.c.num .. ': ' .. s.c.title
    gg:text(24, 20, kit.short(title, 34), { font = kit.font('medium') })
    gg:line(24, 58, W - 24, 58)
    local top, bottom = 70, H - 50
    if s.kind ~= 'none' then
      local b = read(pic(s.kind))
      local okd, im = pcall(function() return b and ctx.image:decode(b, { max_w = W - 16, max_h = bottom - top }) end)
      if okd and im then
        local iw, ih = tonumber(im.width) or 0, tonumber(im.height) or 0
        -- made for this box by the resizer: drawn as it is (the reader's own scaling only adds dots)
        gg:image(im, (W - iw) // 2, top + (bottom - top - ih) // 2)
        pcall(function() im:release() end)
      end
    else
      gg:text(24, 300, 'An interactive comic: open it in the app.', { font = kit.font('medium') })
    end
    local st = stamp(s.at)
    if st then gg:text(W - 24 - kit.width(kit.font('small'), st), H - 34, st, { font = kit.font('small') }) end
  end)
  if not ok then pcall(function() gg:text(10, 760, 'lock error: ' .. tostring(err):sub(1, 40)) end) end
  -- store: cut
  if not pending and not holding then pcall(function() ctx.lock:done() end) end   -- 2.26: nothing more to wait for
  -- store: end
end

function on_load()
  -- store: cut
  pcall(function()
    local hours = tonumber((read('settings.txt') or ''):match('lockevery=(%d+)')) or 6
    if hours <= 0 then hours = 6 end
    local every = hours * 3600
    local s = saved()
    local did = 'not due'
    if not s or not s.at or now_sec() - s.at >= every - SLACK_S then did = try_refresh(s) end
    hold_if_early()
    if holding then did = did .. '; early: held' end
    pcall(function() ctx.lock:set_interval(MAX_WAKE_S) end)
    wlog(string.format('%s lock.net %s every %dh: %s', ctx.lock and tostring(ctx.lock.reason) or '?',
      ctx.lock and tostring(ctx.lock.net) or '?', hours, did))
  end)
  -- store: end
end
function on_tick() end
function on_input() return false end
